window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-65bd49c6775eb9bc"]={"versions": [{"id": "FIG-65bd49c6775eb9bc", "releases": ["R19-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition von Metamodell-Primitivtypen im Kontext der AUTOSAR XML Schema Production Rules (<code>AUTOSAR_TPS_XMLSchemaProductionRules</code>). Das Diagramm illustriert die Modellierungsvorgabe zur Referenzierung vordefinierter W3C-XML-Schema-Datentypen für primitive Klassen des AUTOSAR-Metamodells.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist eine einzelne Modelleinheit:</p>\n<ul class=\"fig-list\">\n<li>Klasse / Primitivtyp: <code>String</code> mit dem Stereotyp <code>«primitive»</code>.</li>\n<li>Tagged Values / Stereotyp-Attribute (<code>tags</code>): <code>xml.xsd.type = string</code>.</li>\n</ul>\n<p class=\"fig-p\">Es existieren keine weiteren Assoziationen, Attribute oder Operationen im Diagramm.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktionen oder Laufzeitsequenzen. Bei der XML-Schema-Generierung fungiert das Modellkonstrukt als Zuordnungsregel: Ein Metamodellelement vom Typ <code>String</code> mit gesetztem Tag <code>xml.xsd.type = string</code> wird direkt auf den vordefinierten Datentyp <code>xsd:string</code> des XML-Schema-Namensraums abgebildet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant gemäß Regel <code>[TPS_XMLSPR_00006]</code>: Für jede Metamodell-Klasse mit Stereotyp <code>«primitive»</code> und definiertem Tagged Value <code>xml.xsd.type</code> wird kein eigener <code>xsd:simpleType</code> deklariert, sondern in generierten XML-Schemata und Instanzen auf den vordefinierten XSD-Typ (Prefix <code>xsd:</code>, hier <code>xsd:string</code>) verwiesen. Generatoren und Schema-Werkzeuge müssen diesen Tagged Value auswerten und die entsprechende Typbindung ohne zusätzliche Neudefinition umsetzen.</p>"}, {"id": "FIG-6d927df0780177bd", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition von Metamodell-Primitivtypen im Kontext der AUTOSAR XML Schema Production Rules (<code>AUTOSAR_TPS_XMLSchemaProductionRules</code>). Das Diagramm illustriert die Modellierungsvorgabe zur Referenzierung vordefinierter W3C-XML-Schema-Datentypen für primitive Klassen des AUTOSAR-Metamodells.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist eine einzelne Modelleinheit:</p>\n<ul class=\"fig-list\">\n<li>Klasse / Primitivtyp: <code>String</code> mit dem Stereotyp <code>«primitive»</code>.</li>\n<li>Tagged Values / Stereotyp-Attribute (<code>tags</code>): <code>xml.xsd.type = string</code>.</li>\n</ul>\n<p class=\"fig-p\">Es existieren keine weiteren Assoziationen, Attribute oder Operationen im Diagramm.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktionen oder Laufzeitsequenzen. Bei der XML-Schema-Generierung fungiert das Modellkonstrukt als Zuordnungsregel: Ein Metamodellelement vom Typ <code>String</code> mit gesetztem Tag <code>xml.xsd.type = string</code> wird direkt auf den vordefinierten Datentyp <code>xsd:string</code> des XML-Schema-Namensraums abgebildet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant gemäß Regel <code>[TPS_XMLSPR_00006]</code>: Für jede Metamodell-Klasse mit Stereotyp <code>«primitive»</code> und definiertem Tagged Value <code>xml.xsd.type</code> wird kein eigener <code>xsd:simpleType</code> deklariert, sondern in generierten XML-Schemata und Instanzen auf den vordefinierten XSD-Typ (Prefix <code>xsd:</code>, hier <code>xsd:string</code>) verwiesen. Generatoren und Schema-Werkzeuge müssen diesen Tagged Value auswerten und die entsprechende Typbindung ohne zusätzliche Neudefinition umsetzen.</p>"}], "trans": [{"from": "FIG-65bd49c6775eb9bc", "to": "FIG-6d927df0780177bd", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-6d927df0780177bd", "to": "FIG-65bd49c6775eb9bc", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
